import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as tslTexture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position, rotation, and scale
  const sp = config.scenePosition || {};
  group.position.set(sp.x ?? 0, sp.y ?? 0, sp.z ?? 0);
  if (sp.rotationXYZ) {
    group.rotation.x = sp.rotationXYZ[0] ?? 0;
    group.rotation.y = sp.rotationXYZ[1] ?? 0;
    group.rotation.z = sp.rotationXYZ[2] ?? 0;
  }
  if (sp.scaleXYZ) {
    group.scale.set(sp.scaleXYZ[0] ?? 1, sp.scaleXYZ[1] ?? 1, sp.scaleXYZ[2] ?? 1);
  }

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture from image URL
  const imageTexture = ctx.textureLoader.load(config.imageUrl);

  // Create material with TSL texture node
  const colorNode = tslTexture(imageTexture);
  const material = new MeshBasicNodeMaterial({
    colorNode,
  });

  // Create and add mesh to group
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Cleanup function for disposal
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
  };

  // Event handlers (none for this static card)
  group.userData.handlers = {};

  return group;
}
